=== db/migrations/001_init.sql
     1	-- 001_init — the three tables and the indexes of docs/spec.md §1,
     2	-- plus article_enrichments.attempts (docs/deviations.md row 7) and
     3	-- articles.headline_text (row 15).
     4	
     5	CREATE TABLE articles (
     6	  id            bigserial PRIMARY KEY,
     7	  external_id   int UNIQUE,                -- the brief's id
     8	  headline      text,                      -- raw, as received; may be '' (article 17)
     9	  headline_text text NOT NULL,             -- HTML stripped, like body_text. Postgres indexes the
    10	                                           -- words inside a tag (img, onerror, …), so the raw
    11	                                           -- headline must not reach to_tsvector
    12	  body          text NOT NULL,             -- raw, unsanitised; the source is evidence
    13	  body_text     text NOT NULL,             -- HTML stripped; used for search and the LLM.
    14	                                           -- NOT NULL: a null here would make tsv null and
    15	                                           -- the article silently unsearchable
    16	  source        text NOT NULL,
    17	  language      text NOT NULL,             -- 'en' | 'ar' | 'zh' | …
    18	  published_at  timestamptz NOT NULL,
    19	  content_hash  bytea NOT NULL,            -- sha256(normalised headline_text + body_text)
    20	  -- The config is a constant in each branch: a config chosen by an expression is
    21	  -- not immutable and a generated column rejects it.
    22	  tsv           tsvector GENERATED ALWAYS AS (
    23	                  CASE WHEN language = 'en'
    24	                    THEN to_tsvector('english', headline_text || ' ' || body_text)
    25	                    ELSE to_tsvector('simple',  headline_text || ' ' || body_text)
    26	                  END) STORED
    27	);
    28	
    29	-- One row per article per run key (requested_model, prompt_version, taxonomy_version):
    30	-- two models over the same articles are two sets of rows.
    31	CREATE TABLE article_enrichments (
    32	  article_id        bigint REFERENCES articles (id),
    33	  requested_model   text,                  -- 'mock', or the model id asked for
    34	  prompt_version    text,
    35	  taxonomy_version  text,
    36	  content_hash      bytea,                 -- the article's hash when this row was produced
    37	  status            text CHECK (status IN ('pending', 'processing', 'done', 'failed')),
    38	  claimed_at        timestamptz,
    39	  summary           text,
    40	  sentiment         text CHECK (sentiment IN ('positive', 'negative', 'neutral', 'mixed')),
    41	  tags              text[],                -- 1..3 ids from the taxonomy
    42	  model             text,                  -- as reported in the provider response
    43	  provider          text,                  -- as reported in the provider response
    44	  input_tokens      int,
    45	  output_tokens     int,
    46	  latency_ms        int,
    47	  cost_usd          numeric(10, 6),
    48	  attempts          int,                   -- provider calls made: 1, or 2 after the retry; null while pending
    49	  error             text,
    50	  updated_at        timestamptz,
    51	  PRIMARY KEY (article_id, requested_model, prompt_version, taxonomy_version)
    52	);
    53	
    54	CREATE TABLE enrichment_budget (
    55	  day          date PRIMARY KEY,           -- UTC
    56	  tokens_used  bigint NOT NULL DEFAULT 0
    57	);
    58	
    59	-- Keyset pagination: the list's ORDER BY, with id as the tiebreak.
    60	CREATE INDEX articles_published_idx
    61	  ON articles (published_at DESC, id DESC);
    62	
    63	-- Source filter: equality column first, then the keyset order and its tiebreak.
    64	CREATE INDEX articles_source_published_idx
    65	  ON articles (source, published_at DESC, id DESC);
    66	
    67	-- Language filter: same shape as the source index.
    68	CREATE INDEX articles_language_published_idx
    69	  ON articles (language, published_at DESC, id DESC);
    70	
    71	-- Boolean search: every leaf is `tsv @@ <tsquery>`.
    72	CREATE INDEX articles_tsv_idx
    73	  ON articles USING gin (tsv);
    74	
    75	-- Topic filter: `tags @> ARRAY[topic]`.
    76	CREATE INDEX article_enrichments_tags_idx
    77	  ON article_enrichments USING gin (tags);
    78	
    79	-- Dedup lookup before a provider call; partial, because only finished rows can be copied.
    80	CREATE INDEX article_enrichments_dedup_idx
    81	  ON article_enrichments (content_hash, requested_model, prompt_version, taxonomy_version)
    82	  WHERE status = 'done';
