     1	// The one place the app's connection pool is created. Query functions under lib/
     2	// take a `Queryable` argument instead of importing the pool, so tests pass the
     3	// media_test database and the scale scripts pass the synthetic one.
     4	import { Pool, type QueryResult, type QueryResultRow } from "pg";
     5	
     6	export interface Queryable {
     7	  query<R extends QueryResultRow = QueryResultRow>(
     8	    text: string,
     9	    values?: unknown[],
    10	  ): Promise<QueryResult<R>>;
    11	}
    12	
    13	let pool: Pool | undefined;
    14	
    15	export function getPool(): Pool {
    16	  if (!pool) {
    17	    const url = process.env.DATABASE_URL;
    18	    if (!url) throw new Error("DATABASE_URL is not set");
    19	    pool = new Pool({ connectionString: url });
    20	  }
    21	  return pool;
    22	}
