=== scripts/migrate.ts
     1	// npm run migrate — applies db/migrations/*.sql in name order, once each.
     2	// Idempotent: applied files are recorded in schema_migrations and skipped.
     3	import { readdirSync, readFileSync } from "node:fs";
     4	import { join } from "node:path";
     5	import { fileURLToPath } from "node:url";
     6	import { Client } from "pg";
     7	
     8	const MIGRATIONS_DIR = fileURLToPath(
     9	  new URL("../db/migrations", import.meta.url),
    10	);
    11	// Any constant: two `init` containers starting together must not both apply a file.
    12	const LOCK_KEY = 7462001;
    13	
    14	/** Applies the pending migrations and returns their file names. */
    15	export async function migrate(client: Client): Promise<string[]> {
    16	  const files = readdirSync(MIGRATIONS_DIR)
    17	    .filter((name) => name.endsWith(".sql"))
    18	    .sort();
    19	  const applied: string[] = [];
    20	
    21	  await client.query("SELECT pg_advisory_lock($1)", [LOCK_KEY]);
    22	  try {
    23	    await client.query(
    24	      "CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())",
    25	    );
    26	    const { rows } = await client.query<{ name: string }>(
    27	      "SELECT name FROM schema_migrations",
    28	    );
    29	    const done = new Set(rows.map((row) => row.name));
    30	
    31	    for (const name of files) {
    32	      if (done.has(name)) continue;
    33	      // The file is a constant from the repo, sent as-is; it takes no parameters.
    34	      const sql = readFileSync(join(MIGRATIONS_DIR, name), "utf8");
    35	      await client.query("BEGIN");
    36	      try {
    37	        await client.query(sql);
    38	        await client.query("INSERT INTO schema_migrations (name) VALUES ($1)", [
    39	          name,
    40	        ]);
    41	        await client.query("COMMIT");
    42	      } catch (error) {
    43	        await client.query("ROLLBACK");
    44	        throw error;
    45	      }
    46	      applied.push(name);
    47	    }
    48	  } finally {
    49	    await client.query("SELECT pg_advisory_unlock($1)", [LOCK_KEY]);
    50	  }
    51	  return applied;
    52	}
    53	
    54	async function main(): Promise<void> {
    55	  const url = process.env.DATABASE_URL;
    56	  if (!url) throw new Error("DATABASE_URL is not set");
    57	  const client = new Client({ connectionString: url });
    58	  await client.connect();
    59	  try {
    60	    const applied = await migrate(client);
    61	    console.log(
    62	      applied.length === 0
    63	        ? "migrate: nothing to apply"
    64	        : "migrate: applied " + applied.join(", "),
    65	    );
    66	  } finally {
    67	    await client.end();
    68	  }
    69	}
    70	
    71	if (process.argv[1] === fileURLToPath(import.meta.url)) {
    72	  main().catch((error) => {
    73	    console.error(error);
    74	    process.exit(1);
    75	  });
    76	}
=== scripts/seed.ts
     1	// npm run seed — loads docs/sample_articles.json into `articles`.
     2	// Idempotent: a re-run inserts 0 rows (spec S1); an existing external_id is left as it is.
     3	import { createHash } from "node:crypto";
     4	import { readFileSync } from "node:fs";
     5	import { fileURLToPath } from "node:url";
     6	import { Client } from "pg";
     7	import type { Queryable } from "../lib/db";
     8	import { stripHtml } from "../lib/html/strip";
     9	
    10	const SAMPLE_FILE = fileURLToPath(
    11	  new URL("../docs/sample_articles.json", import.meta.url),
    12	);
    13	
    14	export type SourceArticle = {
    15	  id: number;
    16	  headline: string;
    17	  body: string;
    18	  source: string;
    19	  published_at: string;
    20	  language: string;
    21	};
    22	
    23	export type ArticleRow = {
    24	  externalId: number;
    25	  headline: string;
    26	  headlineText: string;
    27	  body: string;
    28	  bodyText: string;
    29	  source: string;
    30	  language: string;
    31	  publishedAt: string;
    32	  contentHash: Buffer;
    33	};
    34	
    35	const STRING_FIELDS = [
    36	  "headline",
    37	  "body",
    38	  "source",
    39	  "published_at",
    40	  "language",
    41	] as const;
    42	
    43	/** A type guard for the source file, which is input like any other. */
    44	export function parseArticles(data: unknown): SourceArticle[] {
    45	  if (!Array.isArray(data)) throw new Error("articles: expected an array");
    46	  return data.map((item: unknown, index) => {
    47	    const record = (item ?? {}) as Record<string, unknown>;
    48	    if (!Number.isInteger(record.id)) {
    49	      throw new Error(`articles[${index}]: id must be an integer`);
    50	    }
    51	    for (const field of STRING_FIELDS) {
    52	      if (typeof record[field] !== "string") {
    53	        throw new Error(`articles[${index}]: ${field} must be a string`);
    54	      }
    55	    }
    56	    if (Number.isNaN(Date.parse(record.published_at as string))) {
    57	      throw new Error(`articles[${index}]: published_at is not a date`);
    58	    }
    59	    return record as SourceArticle;
    60	  });
    61	}
    62	
    63	export function loadSampleArticles(): SourceArticle[] {
    64	  return parseArticles(JSON.parse(readFileSync(SAMPLE_FILE, "utf8")));
    65	}
    66	
    67	const normalise = (text: string): string =>
    68	  text.normalize("NFC").replace(/\s+/g, " ").trim();
    69	
    70	/**
    71	 * sha256 over the normalised stripped headline and body text. Normalised = NFC, whitespace
    72	 * runs collapsed, trimmed; case is kept. The newline cannot occur inside either
    73	 * part after normalisation, so it marks where the headline ends.
    74	 */
    75	export function contentHash(headlineText: string, bodyText: string): Buffer {
    76	  return createHash("sha256")
    77	    .update(normalise(headlineText) + "\n" + normalise(bodyText), "utf8")
    78	    .digest();
    79	}
    80	
    81	export function toRow(article: SourceArticle): ArticleRow {
    82	  const headlineText = stripHtml(article.headline);
    83	  const bodyText = stripHtml(article.body);
    84	  return {
    85	    externalId: article.id,
    86	    headline: article.headline, // raw, '' included (article 17)
    87	    headlineText,
    88	    body: article.body,
    89	    bodyText,
    90	    source: article.source,
    91	    language: article.language,
    92	    publishedAt: article.published_at,
    93	    contentHash: contentHash(headlineText, bodyText),
    94	  };
    95	}
    96	
    97	/** Inserts the articles that are not there yet, in one statement; returns how many. */
    98	export async function seed(
    99	  db: Queryable,
   100	  articles: SourceArticle[],
   101	): Promise<number> {
   102	  const rows = articles.map(toRow);
   103	  const result = await db.query(
   104	    `INSERT INTO articles
   105	       (external_id, headline, headline_text, body, body_text, source, language, published_at, content_hash)
   106	     SELECT * FROM unnest(
   107	       $1::int[], $2::text[], $3::text[], $4::text[], $5::text[],
   108	       $6::text[], $7::text[], $8::timestamptz[], $9::bytea[])
   109	     ON CONFLICT (external_id) DO NOTHING`,
   110	    [
   111	      rows.map((r) => r.externalId),
   112	      rows.map((r) => r.headline),
   113	      rows.map((r) => r.headlineText),
   114	      rows.map((r) => r.body),
   115	      rows.map((r) => r.bodyText),
   116	      rows.map((r) => r.source),
   117	      rows.map((r) => r.language),
   118	      rows.map((r) => r.publishedAt),
   119	      rows.map((r) => r.contentHash),
   120	    ],
   121	  );
   122	  return result.rowCount ?? 0;
   123	}
   124	
   125	async function main(): Promise<void> {
   126	  const url = process.env.DATABASE_URL;
   127	  if (!url) throw new Error("DATABASE_URL is not set");
   128	  const articles = loadSampleArticles();
   129	  const client = new Client({ connectionString: url });
   130	  await client.connect();
   131	  try {
   132	    const inserted = await seed(client, articles);
   133	    console.log(`seed: inserted ${inserted} of ${articles.length} articles`);
   134	  } finally {
   135	    await client.end();
   136	  }
   137	}
   138	
   139	if (process.argv[1] === fileURLToPath(import.meta.url)) {
   140	  main().catch((error) => {
   141	    console.error(error);
   142	    process.exit(1);
   143	  });
   144	}
=== lib/articles/filters.ts
     1	// The shared FROM/WHERE builder. The list and the aggregate both take their rows
     2	// from here, so a search result and its chart can never disagree (spec §1).
     3	//
     4	// Every value becomes a `$n` parameter. The SQL text is made of the constants in
     5	// this file and the placeholders `Params.add` returns; no value is ever part of it.
     6	import { filterHash } from "./cursor";
     7	
     8	/** One enrichment run (spec §1, "Run key"). Resolved from the environment by the caller. */
     9	export type RunKey = {
    10	  requestedModel: string;
    11	  promptVersion: string;
    12	  taxonomyVersion: string;
    13	};
    14	
    15	/**
    16	 * The slot for boolean search (phase 2). `build` returns a WHERE fragment over the
    17	 * alias `a`, registering each leaf through `param`; `key` is the query as typed,
    18	 * used only for the cursor's filter hash.
    19	 */
    20	export type SearchFragment = {
    21	  key: string;
    22	  build: (param: (value: unknown) => string) => string;
    23	};
    24	
    25	export type ArticleFilters = {
    26	  source?: string;
    27	  language?: string;
    28	  /** inclusive */
    29	  from?: Date;
    30	  /** exclusive */
    31	  to?: Date;
    32	  /** on the run key's enrichment row */
    33	  sentiment?: string;
    34	  /** a taxonomy id; on the run key's enrichment row */
    35	  topic?: string;
    36	  search?: SearchFragment;
    37	};
    38	
    39	/** Collects parameter values and hands out their placeholders. */
    40	export class Params {
    41	  readonly values: unknown[] = [];
    42	  add = (value: unknown): string => {
    43	    this.values.push(value);
    44	    return "$" + this.values.length;
    45	  };
    46	}
    47	
    48	/**
    49	 * `articles a` joined to its enrichment row for one run key: at most one row per
    50	 * article, because the run key plus article_id is that table's primary key.
    51	 */
    52	export function buildFrom(runKey: RunKey, params: Params): string {
    53	  return [
    54	    "FROM articles a",
    55	    "LEFT JOIN article_enrichments e",
    56	    "  ON e.article_id = a.id",
    57	    "  AND e.requested_model = " + params.add(runKey.requestedModel),
    58	    "  AND e.prompt_version = " + params.add(runKey.promptVersion),
    59	    "  AND e.taxonomy_version = " + params.add(runKey.taxonomyVersion),
    60	  ].join("\n");
    61	}
    62	
    63	/** The filter conditions, ANDed; "TRUE" when there are none. */
    64	export function buildWhere(filters: ArticleFilters, params: Params): string {
    65	  const conditions: string[] = [];
    66	  if (filters.source !== undefined) {
    67	    conditions.push("a.source = " + params.add(filters.source));
    68	  }
    69	  if (filters.language !== undefined) {
    70	    conditions.push("a.language = " + params.add(filters.language));
    71	  }
    72	  if (filters.from !== undefined) {
    73	    conditions.push("a.published_at >= " + params.add(filters.from));
    74	  }
    75	  if (filters.to !== undefined) {
    76	    conditions.push("a.published_at < " + params.add(filters.to));
    77	  }
    78	  if (filters.sentiment !== undefined) {
    79	    conditions.push("e.sentiment = " + params.add(filters.sentiment));
    80	  }
    81	  if (filters.topic !== undefined) {
    82	    // `@>` so the GIN index on tags can serve it
    83	    conditions.push(
    84	      "e.tags @> ARRAY[" + params.add(filters.topic) + "]::text[]",
    85	    );
    86	  }
    87	  if (filters.search !== undefined) {
    88	    conditions.push("(" + filters.search.build(params.add) + ")");
    89	  }
    90	  return conditions.length === 0 ? "TRUE" : conditions.join(" AND ");
    91	}
    92	
    93	/** Identifies a filter set and run key, so a cursor cannot be replayed on another. */
    94	export function filtersHash(filters: ArticleFilters, runKey: RunKey): string {
    95	  return filterHash({
    96	    source: filters.source,
    97	    language: filters.language,
    98	    from: filters.from?.toISOString(),
    99	    to: filters.to?.toISOString(),
   100	    sentiment: filters.sentiment,
   101	    topic: filters.topic,
   102	    q: filters.search?.key,
   103	    run: [runKey.requestedModel, runKey.promptVersion, runKey.taxonomyVersion],
   104	  });
