    55	export async function listArticles(
    56	  db: Queryable,
    57	  request: ListRequest,
    58	): Promise<{ items: ArticleItem[]; nextCursor: string | null }> {
    59	  const limit = Math.min(
    60	    Math.max(Math.trunc(request.limit ?? DEFAULT_LIMIT) || DEFAULT_LIMIT, 1),
    61	    MAX_LIMIT,
    62	  );
    63	  const hash = filtersHash(request.filters, request.runKey);
    64	  const after =
    65	    request.cursor === undefined ? null : decodeCursor(request.cursor, hash);
    66	
    67	  const params = new Params();
    68	  const from = buildFrom(request.runKey, params);
    69	  const conditions = [buildWhere(request.filters, params)];
    70	  if (after) {
