     1	// Counts per time bucket for a filter set (spec §1, Aggregate). Takes the same
     2	// FROM/WHERE as the list. Empty buckets are not zero-filled.
     3	import type { Queryable } from "../db";
     4	import {
     5	  type ArticleFilters,
     6	  buildFrom,
     7	  buildWhere,
     8	  Params,
     9	  type RunKey,
    10	} from "./filters";
    11	
    12	// Whitelists: the request names a key, the SQL gets the constant. Buckets are UTC;
    13	// a week is ISO (starts Monday).
    14	const BUCKETS = {
    15	  week: "date_trunc('week', a.published_at AT TIME ZONE 'UTC')",
    16	  month: "date_trunc('month', a.published_at AT TIME ZONE 'UTC')",
    17	} as const;
    18	
    19	const GROUPS = {
    20	  sentiment: { column: "e.sentiment", join: "" },
    21	  source: { column: "a.source", join: "" },
    22	  // One row per tag: an article with several tags is counted once per tag, so the
    23	  // groups do not sum to the article total. LEFT JOIN keeps un-enriched articles,
    24	  // as group NULL.
    25	  topic: {
    26	    column: "t.tag",
    27	    join: "LEFT JOIN LATERAL unnest(e.tags) AS t(tag) ON TRUE",
    28	  },
    29	} as const;
    30	
    31	export type Bucket = keyof typeof BUCKETS;
    32	export type GroupBy = keyof typeof GROUPS;
    33	export const DEFAULT_BUCKET: Bucket = "week";
    34	
    35	export const isBucket = (value: string): value is Bucket =>
    36	  Object.hasOwn(BUCKETS, value);
    37	export const isGroupBy = (value: string): value is GroupBy =>
    38	  Object.hasOwn(GROUPS, value);
    39	
    40	export type AggregateRequest = {
    41	  filters: ArticleFilters;
    42	  runKey: RunKey;
    43	  bucket?: Bucket;
    44	  groupBy?: GroupBy;
    45	};
    46	
    47	export type AggregateRow = {
    48	  /** first day of the bucket, YYYY-MM-DD, UTC */
    49	  bucket: string;
    50	  /** only with groupBy; null = no enrichment value for that article */
    51	  group?: string | null;
    52	  count: number;
    53	};
    54	
    55	export async function aggregateArticles(
    56	  db: Queryable,
    57	  request: AggregateRequest,
    58	): Promise<AggregateRow[]> {
    59	  const bucket = request.bucket ?? DEFAULT_BUCKET;
    60	  // A key that is not in the whitelist never reaches the SQL text.
    61	  if (!isBucket(bucket)) throw new RangeError("unknown bucket");
    62	  if (request.groupBy !== undefined && !isGroupBy(request.groupBy)) {
    63	    throw new RangeError("unknown group_by");
    64	  }
    65	  const group = request.groupBy ? GROUPS[request.groupBy] : null;
    66	
    67	  const params = new Params();
    68	  const from = buildFrom(request.runKey, params);
    69	  const where = buildWhere(request.filters, params);
    70	  const bucketColumn =
    71	    "to_char(" + BUCKETS[bucket] + ", 'YYYY-MM-DD') AS bucket";
    72	
    73	  const sql = [
    74	    "SELECT " + bucketColumn + ",", // audit: sql-fragment — bucket expression is a constant from the BUCKETS whitelist
    75	    (group ? group.column : "NULL::text") + ' AS "group",',
    76	    "  count(*)::int AS count",
    77	    from,
    78	    group ? group.join : "",
    79	    "WHERE " + where, // audit: sql-fragment — conditions are constants and $n placeholders from filters.ts
    80	    "GROUP BY 1, 2",
    81	    "ORDER BY 1, 2",
    82	  ].join("\n");
    83	
    84	  const { rows } = await db.query<{
    85	    bucket: string;
    86	    group: string | null;
    87	    count: number;
    88	  }>(sql, params.values);
    89	
    90	  return rows.map((row) =>
    91	    group
    92	      ? { bucket: row.bucket, group: row.group, count: row.count }
    93	      : { bucket: row.bucket, count: row.count },
    94	  );
    95	}
