398	    52	export function buildFrom(runKey: RunKey, params: Params): string {
399	    53	  return [
400	    54	    "FROM articles a",
401	    55	    "LEFT JOIN article_enrichments e",
402	    56	    "  ON e.article_id = a.id",
403	    57	    "  AND e.requested_model = " + params.add(runKey.requestedModel),
404	    58	    "  AND e.prompt_version = " + params.add(runKey.promptVersion),
405	    59	    "  AND e.taxonomy_version = " + params.add(runKey.taxonomyVersion),
