409	    63	/** The filter conditions, ANDed; "TRUE" when there are none. */
410	    64	export function buildWhere(filters: ArticleFilters, params: Params): string {
411	    65	  const conditions: string[] = [];
412	    66	  if (filters.source !== undefined) {
413	    67	    conditions.push("a.source = " + params.add(filters.source));
414	    68	  }
415	    69	  if (filters.language !== undefined) {
416	    70	    conditions.push("a.language = " + params.add(filters.language));
417	    71	  }
418	    72	  if (filters.from !== undefined) {
419	    73	    conditions.push("a.published_at >= " + params.add(filters.from));
420	    74	  }
421	    75	  if (filters.to !== undefined) {
