665	     1	// Keyset cursor: base64url of {ts, id, filter_hash} (spec §1, Pagination).
666	     2	//
667	     3	// - `ts` is the row's published_at as text with microseconds, not a JS Date: a
668	     4	//   millisecond round-trip would skip or repeat rows that share a millisecond.
669	     5	// - `id` is the row's internal id, as a string (bigint).
670	     6	// - The cursor is not signed. There is no auth, so a forged cursor only moves the
671	     7	//   position in a public list; both fields are checked before they reach a query.
672	     8	import { createHash } from "node:crypto";
