849	    39	    message: "source must be at most 200 characters",
850	    40	  },
851	    41	  language: {
852	    42	    schema: z.string().regex(/^[a-z]{2,8}$/),
853	    43	    message: "language must be a lowercase code such as en, ar or zh",
854	    44	  },
855	    45	  sentiment: {
856	    46	    schema: z.enum(SENTIMENTS),
857	    47	    message: "sentiment must be one of: " + SENTIMENTS.join(", "),
858	    48	  },
859	    49	  topic: {
