897	    87	/** One parameter, validated; undefined when it is absent or empty. */
898	    88	function read<N extends Name>(
899	    89	  query: URLSearchParams,
900	    90	  name: N,
901	    91	): Value<N> | undefined {
902	    92	  const values = query.getAll(name);
903	    93	  if (values.length > 1) {
904	    94	    throw new ParamError(name + " was given more than once");
