     1	// npm run security-audit — the three deterministic rules of plan §2 (deviation 9):
     2	//
     3	//   mock-no-fetch        lib/enrich/mock.ts makes no network call
     4	//   no-sql-in-routes     app/**/route.ts(x) holds no SQL and no database access
     5	//   no-string-built-sql  no SQL text mixed with an interpolated or concatenated value
     6	//
     7	// Every violation is printed as `FAIL  <rule>  <file>:<line>`; any violation exits 1.
     8	// A path that does not exist yet is printed as NOT CHECKED, so an early green run is
     9	// not read as evidence.
    10	//
    11	// Limits. The rules are line-based regular expressions, not a parser:
    12	// - a template literal nested inside `${…}` can hide the rest of the outer one;
    13	// - SQL keywords are matched in upper case only, apart from whole statements;
    14	// - a line that builds SQL from constants and `$n` placeholders must carry
    15	//   `// audit: sql-fragment — <reason>` on that line or the line above. Every such
    16	//   allowance is printed, so the security-audit skill's traced check reviews each one.
    17	import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
    18	import { join } from "node:path";
    19	import { fileURLToPath } from "node:url";
    20	
    21	export type Finding = {
    22	  rule: string;
    23	  file: string;
    24	  line: number;
    25	  note?: string;
    26	};
    27	export type Result = { violations: Finding[]; allowances: Finding[] };
    28	
    29	const MOCK_PROVIDER = "lib/enrich/mock.ts";
    30	const ROUTE_ROOT = "app";
    31	const SOURCE_ROOTS = ["app", "lib", "components", "scripts"];
    32	const SOURCE_FILE = /\.(ts|tsx|mts|js|jsx|mjs)$/;
    33	const ROUTE_FILE = /(^|\/)route\.tsx?$/;
    34	
    35	const NETWORK_CALL = /\bfetch\s*\(|\bXMLHttpRequest\b|\bWebSocket\s*\(/;
    36	const NETWORK_IMPORT =
    37	  /(from\s+|import\s*\(\s*|require\s*\(\s*)["'](node:)?(http|https|http2|net|tls|dgram|undici|axios|node-fetch|got)["']/;
    38	
    39	const DB_IMPORT =
    40	  /(from\s+|import\s*\(\s*|require\s*\(\s*)["'](pg|[^"']*lib\/db)["']/;
    41	const QUERY_CALL = /\.query\s*\(/;
    42	const SQL_STATEMENT =
    43	  /\bSELECT\b[^;]*\bFROM\b|\bINSERT\s+INTO\b|\bUPDATE\s+\w+\s+SET\b|\bDELETE\s+FROM\b|\b(CREATE|ALTER|DROP)\s+(TABLE|INDEX|DATABASE)\b|\bTRUNCATE\s+\w/i;
    44	const SQL_FRAGMENT =
    45	  /\b(WHERE|ORDER BY|GROUP BY|LIMIT|OFFSET|JOIN|VALUES|RETURNING|ON CONFLICT)\b|@@|\w*tsquery\s*\(|::tsquery|\btsvector\b/;
    46	const CONCATENATION = /["'`]\s*\+|\+\s*["'`]/;
    47	const MARKER = /\/\/\s*audit:\s*sql-fragment\b(.*)$/;
    48	
    49	const isSql = (text: string): boolean =>
    50	  SQL_STATEMENT.test(text) || SQL_FRAGMENT.test(text);
    51	
    52	// Comment lines are blanked, not removed, so line numbers still match the file.
    53	function codeLines(text: string): string[] {
    54	  return text
    55	    .split("\n")
    56	    .map((line) => (/^\s*(\/\/|\*|\/\*)/.test(line) ? "" : line));
    57	}
    58	
    59	export function mockNoFetch(file: string, text: string): Finding[] {
    60	  const out: Finding[] = [];
    61	  codeLines(text).forEach((line, i) => {
    62	    if (NETWORK_CALL.test(line) || NETWORK_IMPORT.test(line)) {
    63	      out.push({ rule: "mock-no-fetch", file, line: i + 1 });
    64	    }
    65	  });
    66	  return out;
    67	}
    68	
    69	export function noSqlInRoutes(file: string, text: string): Finding[] {
    70	  const out: Finding[] = [];
    71	  codeLines(text).forEach((line, i) => {
    72	    if (
    73	      DB_IMPORT.test(line) ||
    74	      QUERY_CALL.test(line) ||
    75	      SQL_STATEMENT.test(line)
    76	    ) {
    77	      out.push({ rule: "no-sql-in-routes", file, line: i + 1 });
    78	    }
    79	  });
    80	  return out;
    81	}
    82	
    83	export function noStringBuiltSql(file: string, text: string): Result {
    84	  const rule = "no-string-built-sql";
    85	  const raw = text.split("\n");
    86	  const lines = codeLines(text);
    87	  const suspect = new Set<number>(); // 0-based line indexes
    88	
    89	  // Template literals, taken whole: SQL on one line and `${…}` on another still counts.
    90	  const code = lines.join("\n");
    91	  const template = /`[^`]*`/g;
    92	  for (let m = template.exec(code); m; m = template.exec(code)) {
    93	    if (!isSql(m[0]) || !m[0].includes("${")) continue;
    94	    const first = code.slice(0, m.index).split("\n").length - 1;
    95	    m[0].split("\n").forEach((part, offset) => {
    96	      if (part.includes("${")) suspect.add(first + offset);
    97	    });
    98	  }
    99	  // String concatenation on a line that holds SQL text.
   100	  lines.forEach((line, i) => {
   101	    if (CONCATENATION.test(line) && isSql(line)) suspect.add(i);
   102	  });
   103	
   104	  const result: Result = { violations: [], allowances: [] };
   105	  for (const i of [...suspect].sort((a, b) => a - b)) {
   106	    const marker = MARKER.exec(raw[i] ?? "") ?? MARKER.exec(raw[i - 1] ?? "");
   107	    const reason = marker?.[1]?.replace(/^[\s—:-]+/, "").trim();
   108	    if (reason)
   109	      result.allowances.push({ rule, file, line: i + 1, note: reason });
   110	    else result.violations.push({ rule, file, line: i + 1 });
   111	  }
   112	  return result;
   113	}
   114	
   115	function walk(dir: string): string[] {
   116	  return readdirSync(dir).flatMap((name) => {
   117	    const path = join(dir, name);
   118	    if (name === "node_modules" || name.startsWith(".")) return [];
   119	    return statSync(path).isDirectory()
   120	      ? walk(path)
   121	      : SOURCE_FILE.test(name)
   122	        ? [path]
   123	        : [];
   124	  });
   125	}
   126	
   127	function main(): number {
   128	  const violations: Finding[] = [];
   129	  const read = (file: string) => readFileSync(file, "utf8");
   130	
   131	  // 1. mock-no-fetch
   132	  if (existsSync(MOCK_PROVIDER)) {
   133	    const found = mockNoFetch(MOCK_PROVIDER, read(MOCK_PROVIDER));
   134	    violations.push(...found);
   135	    if (found.length === 0)
   136	      console.log(`PASS  mock-no-fetch  ${MOCK_PROVIDER}`);
   137	  } else {
   138	    console.log(`NOT CHECKED  mock-no-fetch  ${MOCK_PROVIDER} does not exist`);
   139	  }
   140	
   141	  // 2. no-sql-in-routes
   142	  const routes = existsSync(ROUTE_ROOT)
   143	    ? walk(ROUTE_ROOT).filter((f) => ROUTE_FILE.test(f))
   144	    : [];
   145	  if (routes.length > 0) {
   146	    const found = routes.flatMap((f) => noSqlInRoutes(f, read(f)));
   147	    violations.push(...found);
   148	    if (found.length === 0) {
   149	      console.log(
   150	        `PASS  no-sql-in-routes  ${routes.length} route file(s): ${routes.join(", ")}`,
   151	      );
   152	    }
   153	  } else {
   154	    console.log(
   155	      `NOT CHECKED  no-sql-in-routes  no route file under ${ROUTE_ROOT}/`,
   156	    );
   157	  }
   158	
   159	  // 3. no-string-built-sql
   160	  const roots = SOURCE_ROOTS.filter((dir) => existsSync(dir));
   161	  for (const dir of SOURCE_ROOTS.filter((d) => !roots.includes(d))) {
   162	    console.log(`NOT CHECKED  no-string-built-sql  ${dir}/ does not exist`);
   163	  }
   164	  const sources = roots.flatMap(walk);
   165	  let built = 0;
   166	  for (const file of sources) {
   167	    const result = noStringBuiltSql(file, read(file));
   168	    built += result.violations.length;
   169	    violations.push(...result.violations);
   170	    for (const a of result.allowances) {
   171	      console.log(`ALLOWED  ${a.rule}  ${a.file}:${a.line}  ${a.note}`);
   172	    }
   173	  }
   174	  if (sources.length > 0 && built === 0) {
   175	    console.log(
   176	      `PASS  no-string-built-sql  ${sources.length} file(s) under ${roots.join(", ")}`,
   177	    );
   178	  }
   179	
   180	  for (const v of violations)
   181	    console.log(`FAIL  ${v.rule}  ${v.file}:${v.line}`);
   182	  console.log(
   183	    violations.length === 0
   184	      ? "security-audit: no violations"
   185	      : `security-audit: ${violations.length} violation(s)`,
   186	  );
   187	  return violations.length === 0 ? 0 : 1;
   188	}
   189	
   190	if (process.argv[1] === fileURLToPath(import.meta.url)) {
   191	  process.exit(main());
   192	}
