     1	// The enrichment worker (spec §3), for one run key: enqueue, claim, process.
     2	// One-shot and safe to re-run: only `pending` rows are processed; `done` rows are
     3	// skipped and `failed` rows are left as they are.
     4	import type { Queryable } from "../db";
