   159	/**
   160	 * Dedup (spec §3): a `done` row of this run key with the same content hash is
   161	 * copied instead of calling. The copy keeps the result, `model` and `provider`,
   162	 * and stores null for latency, tokens, cost and attempts: no call was made for
   163	 * it, so metrics count each real call once.
   164	 */
   165	async function copyDone(
   166	  db: Queryable,
   167	  key: RunKey,
   168	  article: Claimed,
   169	): Promise<boolean> {
   170	  const found = await db.query<{
   171	    summary: string;
   172	    sentiment: string;
   173	    tags: string[];
   174	    model: string | null;
   175	    provider: string | null;
   176	  }>(
   177	    `SELECT summary, sentiment, tags, model, provider
   178	       FROM article_enrichments
   179	      WHERE content_hash = $4 AND requested_model = $1 AND prompt_version = $2
   180	        AND taxonomy_version = $3 AND status = 'done'
   181	      LIMIT 1`,
   182	    [...params(key), article.content_hash],
   183	  );
   184	  const row = found.rows[0];
   185	  if (!row) return false;
   186	  await finish(db, key, article, {
   187	    status: "done",
   188	    summary: row.summary,
   189	    sentiment: row.sentiment,
   190	    tags: row.tags,
   191	    model: row.model ?? undefined,
   192	    provider: row.provider ?? undefined,
   193	  });
   194	  return true;
   195	}
   196	
   197	export async function runWorker(
   198	  db: Queryable,
   199	  provider: EnrichmentProvider,
   200	  budget: Budget,
   201	  key: RunKey,
   202	  opts: { concurrency?: number; timeoutMs?: number } = {},
   203	): Promise<WorkerResult> {
   204	  const result: WorkerResult = {
   205	    done: 0,
   206	    failed: 0,
   207	    copied: 0,
   208	    budgetExceeded: false,
   209	  };
   210	  let stop = false;
   211	
   212	  const loop = async (): Promise<void> => {
   213	    while (!stop) {
   214	      const article = await claim(db, key);
   215	      if (!article) return;
   216	      try {
   217	        if (await copyDone(db, key, article)) {
   218	          result.done++;
   219	          result.copied++;
   220	          continue;
   221	        }
   222	        const outcome = await guardedCall(
   223	          provider,
   224	          budget,
   225	          toProviderInput(article),
   226	          { timeoutMs: opts.timeoutMs },
   227	        );
   228	        if (outcome.status === "budget_exceeded") {
   229	          stop = true;
   230	          result.budgetExceeded = true;
   231	          await release(db, key, article.id);
   232	        } else if (outcome.status === "rejected") {
   233	          stop = true;
   234	          result.rejected = outcome.httpStatus;
   235	          await release(db, key, article.id);
   236	        } else if (outcome.status === "done") {
   237	          await finish(db, key, article, { ...outcome, ...outcome.value });
   238	          result.done++;
   239	        } else {
   240	          // Never a default: a failed row has no summary, sentiment or tags.
   241	          await finish(db, key, article, {
   242	            status: "failed",
   243	            error: outcome.error,
   244	            model: outcome.model,
   245	            provider: outcome.provider,
   246	            inputTokens: outcome.inputTokens,
   247	            outputTokens: outcome.outputTokens,
   248	            latencyMs: outcome.latencyMs,
   249	            costUsd: outcome.costUsd,
   250	            attempts: outcome.attempts,
   251	          });
   252	          result.failed++;
   253	          if (outcome.budgetExceeded) {
   254	            stop = true;
   255	            result.budgetExceeded = true;
   256	          }
   257	        }
   258	      } catch (error) {
   259	        stop = true;
   260	        await release(db, key, article.id).catch(() => {});
   261	        throw error;
   262	      }
   263	    }
   264	  };
   265	
   266	  const loops = Math.max(1, opts.concurrency ?? DEFAULT_CONCURRENCY);
   267	  const settled = await Promise.allSettled(Array.from({ length: loops }, loop));
   268	  const failure = settled.find((s) => s.status === "rejected");
   269	  if (failure) throw failure.reason;
   270	  return result;
   271	}
