   273	type Env = Record<string, string | undefined>;
   274	
   275	export function concurrency(env: Env = process.env): number {
   276	  if (!env.ENRICH_CONCURRENCY) return DEFAULT_CONCURRENCY;
   277	  const value = Number(env.ENRICH_CONCURRENCY);
   278	  if (!Number.isInteger(value) || value < 1) {
   279	    throw new Error("ENRICH_CONCURRENCY must be a positive integer");
   280	  }
   281	  return value;
   282	}
   283	
   284	/**
   285	 * `npm run enrich [-- --force]`. Returns the exit code: 0 done, 2 budget_exceeded
   286	 * (nothing further processed), 1 anything else.
   287	 */
   288	export async function enrichCommand(
   289	  db: Queryable,
   290	  env: Env,
   291	  args: string[],
   292	  opts: { provider?: EnrichmentProvider; log?: (line: string) => void } = {},
   293	): Promise<number> {
   294	  const log = opts.log ?? console.log;
   295	  const key = activeRunKey(env);
   296	  const force = args.includes("--force");
   297	  if (force && llmMode(env) === "live") {
   298	    // A forced live run repeats paid calls beyond the one run per model (spec S10).
   299	    log("enrich: --force is refused in live mode");
   300	    return 1;
   301	  }
   302	  const provider = opts.provider ?? createProvider(env);
   303	  const budget = createBudget(db, dailyTokenBudget(env));
   304	  const label = params(key).join(" / ");
   305	
   306	  if (force) await resetRunKey(db, key);
   307	  await enqueue(db, key);
   308	  const result = await runWorker(db, provider, budget, key, {
   309	    concurrency: concurrency(env),
   310	  });
