   312	    `enrich: run key ${label}: done ${result.done} (copied ${result.copied}), failed ${result.failed}`,
   313	  );
   314	
   315	  if (result.rejected !== undefined) {
   316	    log(
   317	      `enrich: the provider refused the request (HTTP ${result.rejected}); the run stopped and unprocessed rows stay pending`,
   318	    );
   319	    return 1;
   320	  }
   321	  if (result.budgetExceeded) {
   322	    const pending = await db.query(
   323	      `SELECT 1 FROM article_enrichments
   324	        WHERE requested_model = $1 AND prompt_version = $2 AND taxonomy_version = $3
   325	          AND status = 'pending'`,
   326	      params(key),
   327	    );
   328	    log(
   329	      `enrich: budget_exceeded: the daily token budget is used up; ${pending.rowCount} row(s) left pending. ` +
   330	        "Run `npm run enrich` (without --force) once the budget allows.",
   331	    );
   332	    return 2;
   333	  }
   334	  return 0;
   335	}
