     1	// The daily token budget (spec §3): reserve, then correct. The reservation is one
     2	// atomic statement, so concurrent calls cannot jointly pass the budget; the only
     3	// overshoot is one call's estimation error. Mock calls reserve too.
     4	import type { Queryable } from "../db";
     5	
     6	/** Used when DAILY_TOKEN_BUDGET is unset. A configuration value, not a measurement. */
     7	export const DEFAULT_DAILY_TOKEN_BUDGET = 1_000_000;
     8	
     9	export type Reservation = { day: string; tokens: number };
    10	
    11	export interface Budget {
    12	  /** Null means the budget cannot take this call: stop. */
    13	  reserve(tokens: number): Promise<Reservation | null>;
    14	  /** Replaces a reservation's estimate with what the provider reported. */
    15	  correct(reservation: Reservation, actualTokens: number): Promise<void>;
    16	}
    17	
    18	export function dailyTokenBudget(
    19	  env: Record<string, string | undefined> = process.env,
    20	): number {
    21	  if (!env.DAILY_TOKEN_BUDGET) return DEFAULT_DAILY_TOKEN_BUDGET;
    22	  const value = Number(env.DAILY_TOKEN_BUDGET);
    23	  if (!Number.isInteger(value) || value < 0) {
    24	    throw new Error("DAILY_TOKEN_BUDGET must be a non-negative integer");
    25	  }
    26	  return value;
    27	}
    28	
    29	export function createBudget(
    30	  db: Queryable,
    31	  limit: number,
    32	  now: () => Date = () => new Date(),
    33	): Budget {
    34	  return {
    35	    async reserve(tokens) {
    36	      const day = now().toISOString().slice(0, 10); // UTC
    37	      // Without today's row the UPDATE below matches nothing and would read as
    38	      // "budget exceeded" on the first call of every day.
    39	      await db.query(
    40	        "INSERT INTO enrichment_budget (day, tokens_used) VALUES ($1, 0) ON CONFLICT (day) DO NOTHING",
    41	        [day],
    42	      );
    43	      const result = await db.query(
    44	        `UPDATE enrichment_budget
    45	            SET tokens_used = tokens_used + $2
    46	          WHERE day = $1 AND tokens_used + $2 <= $3
    47	          RETURNING tokens_used`,
    48	        [day, tokens, limit],
    49	      );
    50	      return result.rowCount === 1 ? { day, tokens } : null;
    51	    },
    52	
    53	    async correct(reservation, actualTokens) {
    54	      // Charged to the day of the reservation, also when the call crossed midnight.
    55	      await db.query(
    56	        "UPDATE enrichment_budget SET tokens_used = tokens_used + $2 WHERE day = $1",
    57	        [reservation.day, actualTokens - reservation.tokens],
    58	      );
    59	    },
    60	  };
    61	}
