    37	};
    38	
    39	export function inputKey(input: ProviderInput): string {
    40	  return createHash("sha256")
    41	    .update(
    42	      JSON.stringify([input.headline ?? null, input.body, input.language]),
    43	      "utf8",
    44	    )
    45	    .digest("hex");
    46	}
    47	
    48	export class MockProvider implements EnrichmentProvider {
    49	  private readonly byKey: Map<string, MockFixture>;
    50	
    51	  constructor(file?: MockFixtureFile) {
    52	    const data =
    53	      file ??
    54	      (JSON.parse(readFileSync(MOCK_FIXTURES_URL, "utf8")) as MockFixtureFile);
    55	    this.byKey = new Map(data.fixtures.map((f) => [f.key, f]));
    56	  }
