595	     6	/** Used when DAILY_TOKEN_BUDGET is unset. A configuration value, not a measurement. */
596	     7	export const DEFAULT_DAILY_TOKEN_BUDGET = 1_000_000;
597	     8	
598	     9	export type Reservation = { day: string; tokens: number };
599	    10	
600	    11	export interface Budget {
601	    12	  /** Null means the budget cannot take this call: stop. */
602	    13	  reserve(tokens: number): Promise<Reservation | null>;
603	    14	  /** Replaces a reservation's estimate with what the provider reported. */
604	    15	  correct(reservation: Reservation, actualTokens: number): Promise<void>;
605	    16	}
606	    17	
607	    18	export function dailyTokenBudget(
608	    19	  env: Record<string, string | undefined> = process.env,
609	    20	): number {
610	    21	  if (!env.DAILY_TOKEN_BUDGET) return DEFAULT_DAILY_TOKEN_BUDGET;
611	    22	  const value = Number(env.DAILY_TOKEN_BUDGET);
612	    23	  if (!Number.isInteger(value) || value < 0) {
613	    24	    throw new Error("DAILY_TOKEN_BUDGET must be a non-negative integer");
614	    25	  }
615	    26	  return value;
616	    27	}
617	    28	
618	    29	export function createBudget(
619	    30	  db: Queryable,
620	    31	  limit: number,
621	    32	  now: () => Date = () => new Date(),
622	    33	): Budget {
623	    34	  return {
624	    35	    async reserve(tokens) {
625	    36	      const day = now().toISOString().slice(0, 10); // UTC
626	    37	      // Without today's row the UPDATE below matches nothing and would read as
627	    38	      // "budget exceeded" on the first call of every day.
628	    39	      await db.query(
629	    40	        "INSERT INTO enrichment_budget (day, tokens_used) VALUES ($1, 0) ON CONFLICT (day) DO NOTHING",
630	    41	        [day],
631	    42	      );
632	    43	      const result = await db.query(
633	    44	        `UPDATE enrichment_budget
634	    45	            SET tokens_used = tokens_used + $2
635	    46	          WHERE day = $1 AND tokens_used + $2 <= $3
636	    47	          RETURNING tokens_used`,
637	    48	        [day, tokens, limit],
638	    49	      );
639	    50	      return result.rowCount === 1 ? { day, tokens } : null;
640	    51	    },
641	    52	
642	    53	    async correct(reservation, actualTokens) {
643	    54	      // Charged to the day of the reservation, also when the call crossed midnight.
644	    55	      await db.query(
645	    56	        "UPDATE enrichment_budget SET tokens_used = tokens_used + $2 WHERE day = $1",
646	    57	        [reservation.day, actualTokens - reservation.tokens],
647	    58	      );
648	    59	    },
649	    60	  };
650	    61	}
